async () => {
  const urls = [
    '/api/spaces?filter=image-to-text&sort=likes&full=true',
    '/api/spaces?pipeline_tag=image-to-text&sort=likes&full=true',
    '/api/spaces?search=image-to-text&sort=likes&full=true'
  ];
  const results = [];
  for (const url of urls) {
    try {
      const r = await fetch(url);
      const text = await r.text();
      results.push({url, status:r.status, text:text.slice(0,2000)});
    } catch(e) { results.push({url, error:String(e)}); }
  }
  return results;
}

async () => {
  const r = await fetch('/api/spaces?filter=image-to-text&sort=likes&full=true');
  const spaces = await r.json();
  return spaces.slice(0,20).map(s => ({id:s.id, author:s.author, title:s.cardData?.title, pipeline_tag:s.cardData?.pipeline_tag, short_description:s.cardData?.short_description, runtime:s.runtime}));
}

async () => {
  const spaces = await (await fetch('/api/spaces?filter=image-to-text&sort=likes&full=true')).json();
  const candidates = spaces.slice(0,10).map(s => s.id);
  const out = [];
  for (const id of candidates) {
    const infoUrl = '/api/spaces/' + encodeURIComponent(id);
    const rtUrl = '/api/spaces/' + encodeURIComponent(id) + '/runtime';
    const row = {id};
    try {
      const info = await (await fetch(infoUrl)).json();
      row.author = info.author;
      row.title = info.cardData?.title || info.id;
      row.sdk = info.sdk || info.cardData?.sdk;
      row.pipeline_tag = info.pipeline_tag || info.cardData?.pipeline_tag;
    } catch(e) { row.infoError = String(e); }
    try {
      const rtResp = await fetch(rtUrl);
      row.runtimeStatus = rtResp.status;
      row.runtime = await rtResp.json();
    } catch(e) { row.runtimeError = String(e); }
    out.push(row);
  }
  return out;
}

async () => {
  const spaces = await (await fetch('/api/spaces?filter=image-to-text&sort=likes&full=true')).json();
  const out = [];
  for (const s of spaces.slice(0,15)) {
    const row = {id:s.id, author:s.author, title:s.cardData?.title, runtimeFromList:s.runtime, likes:s.likes};
    try {
      const info = await (await fetch('/api/spaces/' + s.id)).json();
      row.infoAuthor = info.author;
      row.infoTitle = info.cardData?.title;
      row.infoRuntime = info.runtime;
      row.stage = info.runtime?.stage;
      row.pipeline_tag = info.cardData?.pipeline_tag || info.pipeline_tag;
    } catch(e) { row.infoError = String(e); }
    out.push(row);
  }
  return out;
}
